llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Tretinoin, which shares the complete retinoid backbone, had an absolute oral bioavailability of 52% in humans, directly supporting F≥20% for this retinoid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin, the 13-cis isomer of the same retinoid scaffold, showed approximately 40% systemic bioavailability, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Acitretin, a highly lipophilic aromatic retinoid, had absolute oral bioavailability of about 60% (range 36–95%) after oral dosing with food, showing that lipophilic retinoids can exceed 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Etretinate, a neutral and very lipophilic retinoid ester, had absolute oral bioavailability of about 40%, supporting that lack of an ionizable carboxylic acid does not preclude F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Paracetamol, containing the same p-hydroxyanilide amide substructure, had absolute oral bioavailability of 63% in healthy volunteers, indicating that this moiety is not inherently absorption-limiting.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A tretinoin report described low absolute bioavailability with gut degradation, highlighting variability, but quantitative retinoid studies mostly place F above 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a retinoid p-hydroxyanilide (fenretinide-like). The closest structural analogues—tretinoin, isotretinoin, acitretin, and etretinate—consistently show oral bioavailability values of roughly 25–60%, all above the 20% threshold, despite high lipophilicity and poor aqueous solubility. Paracetamol evidence supports adequate absorption of the p-hydroxyanilide moiety. Although solubility and first-pass metabolism remain concerns, the balance of transferable experimental evidence favors F≥20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide itself in humans or animals.",
    "No direct data on first-pass metabolism of the p-hydroxyanilide group, such as glucuronidation or methylation.",
    "No formulation- or food-effect data for the query molecule; solubility and dissolution are inferred rather than measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

